export default "data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%20261.76%20226.69'%3e%3cpath%20d='M161.096.001l-30.225%2052.351L100.647.001H-.005l130.877%20226.688L261.749.001z'%20fill='%2341b883'/%3e%3cpath%20d='M161.096.001l-30.225%2052.351L100.647.001H52.346l78.526%20136.01L209.398.001z'%20fill='%2334495e'/%3e%3c/svg%3e"
<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue';
import { useRoute, useRouter } from '#imports';
import { useAuthStore } from '@/store/auth';
import { useAuth, useBaseLinks, useSocialIcons } from '@/utils/common';

const { isAuthenticated, currentUsername } = useAuth();
const { socialIcons } = useSocialIcons();
const authStore = useAuthStore();
const route = useRoute();
const router = useRouter();
const isMenuOpen = ref(false);
const { navLinks } = useBaseLinks();

const logoutHandler = () => {
  authStore.logout();
  if (route.path === '/admin') {
    router.push('/auth');
  }
};

watch(
  () => route.fullPath,
  () => {
    isMenuOpen.value = false;
    updateHtmlClass();
  },
);

const updateHtmlClass = () => {
  if (typeof document === 'undefined') return;
  const html = document.documentElement;
  if (isMenuOpen.value) {
    html.classList.add('hidden');
  } else {
    html.classList.remove('hidden');
  }
};

const toggleMenu = () => {
  isMenuOpen.value = !isMenuOpen.value;
  updateHtmlClass();
};

const allNavLinks = computed(() => {
  const links = [...navLinks.value];

  if (import.meta.client && authStore.isAuthenticated && authStore.isAdmin) {
    links.push({ text: 'Админ-панель', href: '/admin' });
  }

  return links;
});

watch(
  () => ({
    isAuthenticated: authStore.isAuthenticated,
    isAdmin: authStore.isAdmin
  }),
  () => {
    void allNavLinks.value;
  },
  { immediate: true }
);
</script>

<template>
  <header :class="['header', { 'bg--dark-gray': isMenuOpen }]">
    <div class="container">
      <div class="header__row">
        <NuxtLink class="logo" to="/">
          <img src="@/assets/logo.svg" alt="logo for header">
        </NuxtLink>

        <div v-if="isAuthenticated" class="name-user text-capitalize">
          /{{ currentUsername }}
        </div>

        <button
          class="toggle"
          :class="{ 'toggle--open': isMenuOpen }"
          type="button"
          @click="toggleMenu"
        >
          <svg viewBox="0 0 800 600">
            <path
              d="M300,220 C300,220 520,220 540,220 C740,220 640,540 520,420 C440,340 300,200 300,200"
              class="top"
            />
            <path d="M300,320 L540,320" class="middle" />
            <path
              d="M300,210 C300,210 520,210 540,210 C740,210 640,530 520,410 C440,330 300,190 300,190"
              class="bottom"
              transform="translate(480, 320) scale(1, -1) translate(-480, -318) "
            />
          </svg>
        </button>

        <div class="social-icons social-icons--pixel header__social">
          <a
            v-for="(icon, index) in socialIcons"
            :key="index"
            :href="icon.link"
            target="_blank"
            rel="noopener noreferrer"
            :class="['social-icons__link', `icon-${icon.name}`]"
          />
        </div>

        <nav class="header__nav">
          <NuxtLink
            v-for="link in allNavLinks"
            :key="link.text"
            class="btn btn--pixel"
            :to="link.href"
          >
            {{ link.text }}
          </NuxtLink>
        </nav>

        <div class="header__auth">
          <NuxtLink
            v-if="!isAuthenticated"
            to="/auth"
            class="btn-login btn btn--pixel"
          >
            Вход/Регистрация
          </NuxtLink>
          <button
            v-else
            class="btn-logout btn btn--pixel"
            type="button"
            @click="logoutHandler"
          >
            Выйти
          </button>
        </div>
      </div>
    </div>

    <transition name="fade">
      <aside v-if="isMenuOpen" class="nav">
        <ul class="nav__list">
          <li
            v-for="link in allNavLinks"
            :key="link.text"
            class="mobile btn btn--pixel"
          >
            <NuxtLink
              :to="link.href"
              @click="isMenuOpen = false"
            >
              {{ link.text }}
            </NuxtLink>
          </li>

          <li
            v-if="!isAuthenticated"
            class="btn-login btn btn--pixel"
          >
            <NuxtLink to="/auth" @click="isMenuOpen = false">
              Вход / Регистрация
            </NuxtLink>
          </li>
          <li
            v-else
            class="btn-logout btn btn--pixel"
          >
            <button type="button" @click="logoutHandler">
              Выйти
            </button>
          </li>

          <li class="social-icons">
            <a
              v-for="(icon, index) in socialIcons"
              :key="index"
              :href="icon.link"
              target="_blank"
              rel="noopener noreferrer"
              :class="['social-icons__link', `icon-${icon.name}`]"
            />
          </li>
        </ul>
      </aside>
    </transition>
  </header>
</template>
<script setup lang="ts">
import { useAuth, useSocialIcons, useBaseLinks } from '@/utils/common';

const { navLinks } = useBaseLinks();
const { socialIcons } = useSocialIcons();
const { isAuthenticated, currentUsername } = useAuth();
</script>

<template>
  <footer class="footer">
    <div class="container">
      <div class="row">
        <nav class="footer__nav">
          <NuxtLink
            v-for="link in navLinks"
            :key="link.text"
            class="btn btn--pixel"
            :to="link.href"
          >
            {{ link.text }}
          </NuxtLink>
        </nav>
        <hr class="hr-pixel footer__divider-mobile">
        <div class="social-icons social-icons--pixel">
          <a
            v-for="(icon, index) in socialIcons"
            :key="index"
            :href="icon.link"
            target="_blank"
            rel="noopener noreferrer"
            :class="['social-icons__link', `icon-${icon.name}`]"
          />
        </div>
        <hr class="hr-pixel">

        <div class="footer__desc">
          Phasellus feugiat arcu sapien, et iaculis ipsum elementum sit amet.
          Mauris cursus commodo interdum. Praesent ut risus eget metus luctus accumsan id ultrices nunc.
          Sed at orci sed massa consectetur dignissim a sit amet dui. Duis commodo vitae velit et faucibus.
          Morbi vehicula lacinia malesuada. Nulla placerat augue vel ipsum ultrices, cursus iaculis dui sollicitudin.
          Vestibulum eu ipsum vel diam elementum tempor vel ut orci. Orci varius natoque penatibus et magnis dis parturient montes, nascetur ridiculus mus.
        </div>
        <hr class="hr-pixel">
        <div class="footer__info">
          Все права защищены {{ new Date().getFullYear() }}г.
          <span
            v-if="isAuthenticated"
            class="name-user text-capitalize"
          >
            /{{ currentUsername }}
          </span>
          <NuxtLink class="logo" to="/">
            <img src="@/assets/logo.svg" alt="logo for footer">
          </NuxtLink>
        </div>
      </div>
    </div>
  </footer>
</template>
<script setup lang="ts">
import { computed } from 'vue';
import { useRoute } from '#imports';
import Header from '@/components/header.vue';
import Footer from '@/components/footer.vue';

const route = useRoute();

const pageClassByRoute: Record<string, string> = {
  index: 'home-page',
  home: 'home-page',
  about: 'about-page',
  learn: 'learn-page',
  blog: 'blog-page',
  'blog-id': 'article-page',
  auth: 'auth-page',
  admin: 'admin-page',
  'parallax-container': 'parallax-page',
};

const pageClass = computed(() => {
  const name = String(route.name ?? '');
  return pageClassByRoute[name] ?? '';
});
</script>

<template>
  <div class="app">
    <Header />
    <main :class="pageClass">
      <slot />
    </main>
    <Footer />
  </div>
</template>

<style scoped lang="scss">
.app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}
</style>
